cd C:/Users/dasbl/AppData/Local/Temp/claude/adr-probes/0016 && cat > p4.gd <<'EOF'
extends SceneTree
class Scratch extends RefCounted:
	var cols: Dictionary = {}
	var peer: Scratch = null
class Live extends RefCounted:
	var a: PackedInt64Array = PackedInt64Array()
	var b: PackedInt32Array = PackedInt32Array()

func restore_once(live: Live, leak: bool) -> void:
	var s := Scratch.new()
	s.cols["a"] = PackedInt64Array([1, 2, 3, 4])
	s.cols["b"] = PackedInt32Array([5, 6])
	if leak:
		var t := Scratch.new()
		s.peer = t
		t.peer = s
	live.a = (s.cols["a"] as PackedInt64Array).duplicate()
	live.b = (s.cols["b"] as PackedInt32Array).duplicate()

func _init() -> void:
	var live := Live.new()
	restore_once(live, false)
	var base := int(Performance.get_monitor(Performance.OBJECT_COUNT))
	for i in 100:
		restore_once(live, false)
	var after_clean := int(Performance.get_monitor(Performance.OBJECT_COUNT))
	for i in 100:
		restore_once(live, true)
	var after_leak := int(Performance.get_monitor(Performance.OBJECT_COUNT))
	print("base=", base, " clean_delta=", after_clean - base, " cycle_delta=", after_leak - after_clean)
	quit()
EOF
